//! Generated files, write mode and check mode (one `Mode` for every generator).

use std::path::{Path, PathBuf};

use clap::ValueEnum as _;
use similar::TextDiff;

use crate::out::emit;

/// Whether a run writes generated files or only compares them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Write every file, creating directories as needed.
    Write,
    /// Write nothing; report differences (GEN001).
    Check,
}

/// One generated file: a repo-relative path and its full content.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GenFile {
    /// Path relative to the output root, with `/` separators.
    pub path: String,
    /// Complete file content.
    pub content: String,
}

/// Failure to read or write a generated file.
#[derive(Debug, thiserror::Error)]
pub enum FilesError {
    /// An I/O operation on a generated path failed.
    #[error("{op} {path}: {source}")]
    Io {
        /// What was attempted.
        op: &'static str,
        /// The path involved.
        path: PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
}

/// Most diff lines printed per differing file in check mode; the rest is summarized.
pub const DIFF_CAP_LINES: usize = 60;

/// The text every generator puts in its marker, followed by the generating command.
const MARKER_PREFIX: &str = "generated by ";

/// The command words that follow the prefix (an optional backtick may come first).
const MARKER_COMMAND: &str = "cargo dev gen ";

// (the prefix is matched in lower case, so `GENERATED by` and `generated by` both count)

/// Generated pages that quote deliberately broken example documents; their links are fixtures, not navigation.
const EXAMPLE_PAGES: &str = "docs/reference/rules/";

/// Lines from the top of a file in which its marker must appear.
const MARKER_WINDOW: usize = 5;

/// Result of applying a set of files under a root.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Applied {
    /// Files whose content changed (write mode) or differs (check mode).
    pub differing: usize,
    /// Files examined.
    pub total: usize,
    /// Check mode only: marker and orphan problems found (missing marker, unknown command, orphan file).
    pub marker_problems: usize,
}

/// Write or check `files` under `root`; in check mode print a unified diff per differing file.
///
/// # Errors
/// Returns [`FilesError`] when a file cannot be read (other than missing) or written.
pub fn apply(root: &Path, files: &[GenFile], mode: Mode) -> Result<Applied, FilesError> {
    let mut applied = Applied {
        differing: 0,
        total: files.len(),
        marker_problems: 0,
    };
    if mode == Mode::Check {
        for problem in orphan_files(root, files) {
            applied.marker_problems += 1;
            emit(&format!(
                "GEN001: {problem}: generated file that no generator produces; delete it"
            ));
        }
    }
    if mode == Mode::Check {
        for problem in link_problems(root, files)
            .into_iter()
            .chain(summary_problems(root))
        {
            applied.marker_problems += 1;
            emit(&format!("GEN001: {problem}"));
        }
    }
    for file in files {
        let target = root.join(&file.path);
        let existing = match std::fs::read_to_string(&target) {
            Ok(text) => Some(text),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
            Err(source) => {
                return Err(FilesError::Io {
                    op: "read",
                    path: target,
                    source,
                });
            }
        };
        let same = existing.as_deref() == Some(file.content.as_str());
        match mode {
            Mode::Check => {
                if !same {
                    tracing::warn!(path = %file.path, missing = existing.is_none(), "generated file differs");
                    applied.differing += 1;
                    emit(&cap_diff(
                        &unified_diff(&file.path, existing.as_deref(), &file.content),
                        DIFF_CAP_LINES,
                    ));
                }
                // frob:ticket 01M47QTW8CA2FD3BQTH2GG2KXR
                // Inline inputs are parser source text and cannot carry a marker.
                let inline = crate::render::inline::is_inline_path(&file.path);
                if !inline
                    && let Some(text) = existing.as_deref()
                    && let Some(problem) = marker_problem(text)
                {
                    applied.marker_problems += 1;
                    emit(&format!("GEN001: {}: {problem}", file.path));
                }
                // frob:ticket 01M4MAQ5JFANPHZ0SJ690R68TZ
                if !inline
                    && let Some(text) = existing.as_deref()
                    && let Some(warning) = stale_version(text, crate::render::GENERATOR_VERSION)
                {
                    emit(&format!("GEN001 (warning): {}: {warning}", file.path));
                }
            }
            Mode::Write => {
                if same {
                    tracing::debug!(path = %file.path, "unchanged");
                } else {
                    if let Some(parent) = target.parent() {
                        std::fs::create_dir_all(parent).map_err(|source| FilesError::Io {
                            op: "create dir",
                            path: parent.to_path_buf(),
                            source,
                        })?;
                    }
                    std::fs::write(&target, &file.content).map_err(|source| FilesError::Io {
                        op: "write",
                        path: target.clone(),
                        source,
                    })?;
                    tracing::info!(path = %file.path, "wrote");
                    applied.differing += 1;
                    emit(&format!("wrote {}", file.path));
                }
            }
        }
    }
    Ok(applied)
}

/// Unified diff of `old` (None means the file is missing) against `new` for `path`.
pub fn unified_diff(path: &str, old: Option<&str>, new: &str) -> String {
    let old_header = if old.is_some() {
        format!("a/{path}")
    } else {
        "/dev/null".to_owned()
    };
    let new_header = format!("b/{path}");
    TextDiff::from_lines(old.unwrap_or(""), new)
        .unified_diff()
        .context_radius(3)
        .header(&old_header, &new_header)
        .to_string()
}

// frob:ticket 01M3ZX85N2KZ39PG65MX0YT2P0
/// Keep the first `max` lines of `diff` and say how many were left out.
pub fn cap_diff(diff: &str, max: usize) -> String {
    let total = diff.lines().count();
    if total <= max {
        return diff.to_owned();
    }
    let mut out: Vec<&str> = diff.lines().take(max).collect();
    let note = format!("... {} more diff lines not shown", total - max);
    out.push(&note);
    out.join("\n")
}

// frob:ticket 01M3ZX85N2KZ39PG65MX0YT2P0
/// The marker line of `text`: the first of its top lines that holds `generated by ` in any letter case.
fn marker_line(text: &str) -> Option<&str> {
    text.lines()
        .take(MARKER_WINDOW)
        .find(|l| l.to_ascii_lowercase().contains(MARKER_PREFIX))
}

/// The generating command a file's marker names, looking at its first few lines.
pub fn marker_command(text: &str) -> Option<&str> {
    let line = marker_line(text)?;
    let rest = &line[line.find(MARKER_COMMAND)? + MARKER_COMMAND.len()..];
    let end = rest
        .find(|c: char| !(c.is_ascii_alphanumeric() || c == '-' || c == '_'))
        .unwrap_or(rest.len());
    Some(&rest[..end])
}

// frob:ticket 01M4MAQ5JFANPHZ0SJ690R68TZ
/// The generator version a file's marker records (`frob v<version>:`), when it has the versioned form.
pub fn marker_version(text: &str) -> Option<&str> {
    let line = marker_line(text)?;
    let rest = &line[line.find("frob v")? + "frob v".len()..];
    let end = rest.find(':')?;
    Some(&rest[..end])
}

// frob:ticket 01M4MAQ5JFANPHZ0SJ690R68TZ
/// The GEN001 warning for a generated file whose marker version differs from `current`, if any.
pub fn stale_version(text: &str, current: &str) -> Option<String> {
    let found = marker_version(text)?;
    (found != current).then(|| {
        format!("marker records generator v{found} but the generator is v{current}; regenerate")
    })
}

// frob:ticket 01M3ZX85N2KZ39PG65MX0YT2P0
/// What is wrong with the marker of generated file `text`: missing, or naming a command `gen` does not have.
pub fn marker_problem(text: &str) -> Option<String> {
    let Some(command) = marker_command(text) else {
        return Some("no generated marker in the first lines".to_owned());
    };
    let known = crate::Kind::value_variants().iter().any(|k| {
        k.to_possible_value()
            .is_some_and(|v| v.get_name() == command)
    });
    (!known).then(|| format!("marker names the missing command `cargo dev gen {command}`"))
}

// frob:ticket 01M3ZX85N2KZ39PG65MX0YT2P0
/// Files beside the generated ones that carry a generated marker but are not in `files`.
fn orphan_files(root: &Path, files: &[GenFile]) -> Vec<String> {
    let known: std::collections::BTreeSet<&str> = files.iter().map(|f| f.path.as_str()).collect();
    let dirs: std::collections::BTreeSet<&str> = files
        .iter()
        .map(|f| f.path.rsplit_once('/').map_or("", |(d, _)| d))
        .collect();
    let mut orphans = Vec::new();
    for dir in dirs {
        let Ok(entries) = std::fs::read_dir(root.join(dir)) else {
            continue;
        };
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let rel = if dir.is_empty() {
                name
            } else {
                format!("{dir}/{name}")
            };
            if known.contains(rel.as_str()) || !entry.path().is_file() {
                continue;
            }
            // frob:ticket 01M47QTW8CA2FD3BQTH2GG2KXR
            // An extracted inline input has no marker; any unknown file in its directory is stale.
            let stale_inline = crate::render::inline::is_inline_path(&rel);
            if stale_inline
                || std::fs::read_to_string(entry.path())
                    .is_ok_and(|text| marker_command(&text).is_some())
            {
                orphans.push(rel);
            }
        }
    }
    orphans.sort();
    orphans
}

// frob:ticket 01M4NWPZHG4X7QEJKETA5JNS96
/// The relative link targets of markdown `text`, outside fenced code and inline code spans, with fragments and queries removed.
pub fn relative_links(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut fenced = false;
    for line in text.lines() {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
            continue;
        }
        if fenced {
            continue;
        }
        let plain: String = line.split('`').step_by(2).collect::<Vec<_>>().join(" ");
        let mut rest = plain.as_str();
        while let Some(at) = rest.find("](") {
            rest = &rest[at + 2..];
            let end = rest.find([')', ' ']).unwrap_or(rest.len());
            let raw = &rest[..end];
            let path = raw.split(['#', '?']).next().unwrap_or("");
            let external = raw.contains("://") || raw.starts_with("mailto:");
            if !path.is_empty() && !external && !path.starts_with('/') {
                out.push(path.to_owned());
            }
        }
    }
    out
}

// frob:ticket 01M4NWPZHG4X7QEJKETA5JNS96
/// GEN001 problems for generated markdown whose relative links name a path that exists neither on disk nor among `files`.
fn link_problems(root: &Path, files: &[GenFile]) -> Vec<String> {
    let known: std::collections::BTreeSet<&str> = files.iter().map(|f| f.path.as_str()).collect();
    let mut problems = Vec::new();
    for file in files
        .iter()
        .filter(|f| is_markdown(&f.path) && !f.path.starts_with(EXAMPLE_PAGES))
    {
        let dir = file.path.rsplit_once('/').map_or("", |(d, _)| d);
        for link in relative_links(&file.content) {
            let Some(joined) = normalize(dir, &link) else {
                problems.push(format!(
                    "{}: link `{link}` leaves the repository",
                    file.path
                ));
                continue;
            };
            if !known.contains(joined.as_str()) && !root.join(&joined).exists() {
                tracing::warn!(path = %file.path, %link, "relative link does not resolve");
                problems.push(format!("{}: link `{link}` does not resolve", file.path));
            }
        }
    }
    problems
}

/// Join `link` onto `dir` (both `/`-separated), folding `.` and `..`; `None` when it climbs above the root.
fn normalize(dir: &str, link: &str) -> Option<String> {
    let mut parts: Vec<&str> = dir.split('/').filter(|p| !p.is_empty()).collect();
    for seg in link.split('/') {
        match seg {
            "" | "." => {}
            ".." => {
                parts.pop()?;
            }
            other => parts.push(other),
        }
    }
    Some(parts.join("/"))
}

// frob:ticket 01M4NWPZHG4X7QEJKETA5JNS96
/// GEN001 problems for `docs/SUMMARY.md`, when present: every other docs page must be linked from it.
fn summary_problems(root: &Path) -> Vec<String> {
    let Ok(summary) = std::fs::read_to_string(root.join("docs/SUMMARY.md")) else {
        return Vec::new();
    };
    let linked: std::collections::BTreeSet<String> = relative_links(&summary)
        .iter()
        .filter_map(|l| normalize("docs", l))
        .collect();
    let mut pages = Vec::new();
    let mut stack = vec![(root.join("docs"), "docs".to_owned())];
    while let Some((dir, rel)) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let child = format!("{rel}/{name}");
            if entry.path().is_dir() {
                stack.push((entry.path(), child));
            } else if is_markdown(&name) && child != "docs/SUMMARY.md" {
                pages.push(child);
            }
        }
    }
    pages.sort();
    pages
        .into_iter()
        .filter(|p| !linked.contains(p))
        .map(|p| format!("{p}: docs page missing from docs/SUMMARY.md"))
        .collect()
}

/// Whether `path` names a markdown file (extension compared without regard to case).
fn is_markdown(path: &str) -> bool {
    Path::new(path)
        .extension()
        .is_some_and(|e| e.eq_ignore_ascii_case("md"))
}
